USE ImportFile;
GO
CREATE OR ALTER PROCEDURE dbo.load_trade_result_from_string_buffer
AS
BEGIN
  SET NOCOUNT ON;
  INSERT INTO dbo.stg_trade_result_typed_target (
    [tradedate], [securityid], [isin], [secshortname], [issuername], [seccategory], [quotelist], [currencyid], [seccurrencyid], [facevalue], [settlementcurrency], [accruedinterest], [isaddress], [setttype], [trademode], [totalvolume], [totalamount], [totaldealcount], [maxdealprice], [mindealprice], [closeprice], [prevclose], [trendclose], [waprice], [marketprice2], [mp2volume], [marketprice3], [mp3volume], [currentprice], [firstcurrentprice], [trendcurrentprice], [averagedailyvolume], [clearingprice], [trendclearingprice], [mornopenvolume], [mornopenamount], [mornopenprice], [mornlastvolume], [mornlastamount], [mornlastprice], [mornmaxdealprice], [mornmindealprice], [morntotalvolume], [morntotalamount], [morntotalcount], [mornwaprice], [morncurrentprice], [mainopenvolume], [mainopenamount], [mainopenprice], [mainlastvolume], [mainlastamount], [mainlastprice], [mainmaxdealprice], [mainmindealprice], [maintotalvolume], [maintotalamount], [maintotalcount], [mainwaprice], [maincurrentprice], [eveopenvolume], [eveopenamount], [eveopenprice], [evelastvolume], [evelastamount], [evelastprice], [evemaxdealprice], [evemindealprice], [evetotalvolume], [evetotalamount], [evetotalcount], [evewaprice], [evecurrentprice]
  )
  SELECT
    TRY_CONVERT(date, NULLIF(LTRIM(RTRIM(s.[tradedate])), '')) AS [tradedate],
    CONVERT(nvarchar(512), s.[securityid]) AS [securityid],
    CONVERT(nvarchar(512), s.[isin]) AS [isin],
    CONVERT(nvarchar(512), s.[secshortname]) AS [secshortname],
    CONVERT(nvarchar(512), s.[issuername]) AS [issuername],
    CONVERT(nvarchar(512), s.[seccategory]) AS [seccategory],
    CONVERT(nvarchar(512), s.[quotelist]) AS [quotelist],
    CONVERT(nvarchar(512), s.[currencyid]) AS [currencyid],
    CONVERT(nvarchar(512), s.[seccurrencyid]) AS [seccurrencyid],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[facevalue], ',', '.'))), '')) AS [facevalue],
    CONVERT(nvarchar(512), s.[settlementcurrency]) AS [settlementcurrency],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[accruedinterest], ',', '.'))), '')) AS [accruedinterest],
    CONVERT(nvarchar(512), s.[isaddress]) AS [isaddress],
    CONVERT(nvarchar(512), s.[setttype]) AS [setttype],
    CONVERT(nvarchar(512), s.[trademode]) AS [trademode],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[totalvolume], ',', '.'))), '')) AS [totalvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[totalamount], ',', '.'))), '')) AS [totalamount],
    TRY_CONVERT(bigint, NULLIF(LTRIM(RTRIM(REPLACE(s.[totaldealcount], ',', '.'))), '')) AS [totaldealcount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[maxdealprice], ',', '.'))), '')) AS [maxdealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mindealprice], ',', '.'))), '')) AS [mindealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[closeprice], ',', '.'))), '')) AS [closeprice],
    CONVERT(nvarchar(512), s.[prevclose]) AS [prevclose],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[trendclose], ',', '.'))), '')) AS [trendclose],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[waprice], ',', '.'))), '')) AS [waprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[marketprice2], ',', '.'))), '')) AS [marketprice2],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mp2volume], ',', '.'))), '')) AS [mp2volume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[marketprice3], ',', '.'))), '')) AS [marketprice3],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mp3volume], ',', '.'))), '')) AS [mp3volume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[currentprice], ',', '.'))), '')) AS [currentprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[firstcurrentprice], ',', '.'))), '')) AS [firstcurrentprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[trendcurrentprice], ',', '.'))), '')) AS [trendcurrentprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[averagedailyvolume], ',', '.'))), '')) AS [averagedailyvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[clearingprice], ',', '.'))), '')) AS [clearingprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[trendclearingprice], ',', '.'))), '')) AS [trendclearingprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornopenvolume], ',', '.'))), '')) AS [mornopenvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornopenamount], ',', '.'))), '')) AS [mornopenamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornopenprice], ',', '.'))), '')) AS [mornopenprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornlastvolume], ',', '.'))), '')) AS [mornlastvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornlastamount], ',', '.'))), '')) AS [mornlastamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornlastprice], ',', '.'))), '')) AS [mornlastprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornmaxdealprice], ',', '.'))), '')) AS [mornmaxdealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornmindealprice], ',', '.'))), '')) AS [mornmindealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[morntotalvolume], ',', '.'))), '')) AS [morntotalvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[morntotalamount], ',', '.'))), '')) AS [morntotalamount],
    TRY_CONVERT(bigint, NULLIF(LTRIM(RTRIM(REPLACE(s.[morntotalcount], ',', '.'))), '')) AS [morntotalcount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mornwaprice], ',', '.'))), '')) AS [mornwaprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[morncurrentprice], ',', '.'))), '')) AS [morncurrentprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainopenvolume], ',', '.'))), '')) AS [mainopenvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainopenamount], ',', '.'))), '')) AS [mainopenamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainopenprice], ',', '.'))), '')) AS [mainopenprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainlastvolume], ',', '.'))), '')) AS [mainlastvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainlastamount], ',', '.'))), '')) AS [mainlastamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainlastprice], ',', '.'))), '')) AS [mainlastprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainmaxdealprice], ',', '.'))), '')) AS [mainmaxdealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainmindealprice], ',', '.'))), '')) AS [mainmindealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[maintotalvolume], ',', '.'))), '')) AS [maintotalvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[maintotalamount], ',', '.'))), '')) AS [maintotalamount],
    TRY_CONVERT(bigint, NULLIF(LTRIM(RTRIM(REPLACE(s.[maintotalcount], ',', '.'))), '')) AS [maintotalcount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[mainwaprice], ',', '.'))), '')) AS [mainwaprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[maincurrentprice], ',', '.'))), '')) AS [maincurrentprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[eveopenvolume], ',', '.'))), '')) AS [eveopenvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[eveopenamount], ',', '.'))), '')) AS [eveopenamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[eveopenprice], ',', '.'))), '')) AS [eveopenprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evelastvolume], ',', '.'))), '')) AS [evelastvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evelastamount], ',', '.'))), '')) AS [evelastamount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evelastprice], ',', '.'))), '')) AS [evelastprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evemaxdealprice], ',', '.'))), '')) AS [evemaxdealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evemindealprice], ',', '.'))), '')) AS [evemindealprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evetotalvolume], ',', '.'))), '')) AS [evetotalvolume],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evetotalamount], ',', '.'))), '')) AS [evetotalamount],
    TRY_CONVERT(bigint, NULLIF(LTRIM(RTRIM(REPLACE(s.[evetotalcount], ',', '.'))), '')) AS [evetotalcount],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evewaprice], ',', '.'))), '')) AS [evewaprice],
    TRY_CONVERT(decimal(28,8), NULLIF(LTRIM(RTRIM(REPLACE(s.[evecurrentprice], ',', '.'))), '')) AS [evecurrentprice]
  FROM dbo.stg_trade_result_string_buffer s;
END;
GO
